import{_ as i,o as n,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- OSD: Tiering","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- OSD: Tiering","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","分布式存储","分层存储","动态数据迁移","插件接口"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Tiering.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Tiering.md","lastUpdated":1780459816000}'),s={name:"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Tiering.md"};function o(p,l,e,g,_,a){return n(),t("div",null,[...l[0]||(l[0]=[r("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： [请填写会议具体时间]</p><p><strong>会议地点</strong>： [请填写会议具体地点]</p><p><strong>参会人员</strong>：</p><ul><li>Sam A.</li><li>Shikang</li><li>其他Intel研发人员</li></ul><p><strong>会议主题</strong>：</p><ul><li>Ceph分布式存储系统中的分层存储和动态数据迁移</li></ul><p><strong>会议内容</strong>：</p><p><strong>一、分层存储</strong></p><ol><li><p><strong>背景</strong>：</p><ul><li>当前Ceph支持分层存储，包括热层、温层和冷层。</li><li>会议讨论了如何扩展分层存储功能，使其能够将冷数据迁移到更便宜的存储系统中，例如不同数据中心的其他Ceph集群或S3。</li></ul></li><li><p><strong>讨论</strong>：</p><ul><li><strong>插件接口</strong>： <ul><li>Sam A. 提出创建一个插件系统，允许将冷数据迁移到指定的插件存储系统中。</li><li>该接口应仅支持追加操作，不允许修改对象名称，以简化后端实现。</li><li>需要考虑慢速后端（如Glacier或磁带机）的处理，可能需要实现进度指示和错误代码传播。</li></ul></li><li><strong>元数据管理</strong>： <ul><li>需要在Ceph元数据中记录迁移信息，以便在恢复时使用。</li><li>需要考虑快照和写操作对迁移的影响。</li></ul></li></ul></li><li><p><strong>决定</strong>：</p><ul><li>开始实现插件接口，并考虑慢速后端的支持。</li><li>在插件接口中添加进度指示和错误代码传播功能。</li><li>在元数据中记录迁移信息。</li></ul></li></ol><p><strong>二、动态数据迁移</strong></p><ol><li><p><strong>背景</strong>：</p><ul><li>会议讨论了在Ceph中实现动态数据迁移的功能，以便在分层存储之间动态迁移数据。</li></ul></li><li><p><strong>讨论</strong>：</p><ul><li><strong>多级分层存储</strong>： <ul><li>Shikang 提出在Ceph中实现多级分层存储，包括热层、温层、冷层和更冷的存储系统。</li><li>需要考虑如何管理元数据和对象迁移。</li></ul></li><li><strong>手动和自动迁移</strong>： <ul><li>可以通过命令行工具手动迁移数据，也可以实现自动迁移功能。</li><li>可以使用现有的pin和unpin功能来实现数据迁移。</li></ul></li></ul></li><li><p><strong>决定</strong>：</p><ul><li>开始实现多级分层存储功能。</li><li>添加手动和自动数据迁移功能。</li></ul></li></ol><p><strong>三、其他</strong></p><ol><li><strong>插件接口的智能性</strong>： <ul><li>讨论了是否需要将插件接口设计得更加智能，例如支持部分覆盖操作。</li><li>认为对于冷数据存储，部分覆盖操作的优势不大。</li><li>认为在支持部分覆盖操作时，需要考虑复杂性和性能问题。</li></ul></li></ol><p><strong>后续行动计划</strong>：</p><ul><li>实现分层存储插件接口。</li><li>实现多级分层存储功能。</li><li>添加手动和自动数据迁移功能。</li><li>在邮件列表上收集更多反馈。</li></ul><p><strong>备注</strong>：</p><ul><li>会议讨论了分层存储和动态数据迁移的多个方面，包括插件接口、元数据管理、数据迁移策略等。</li><li>需要根据实际需求和反馈进一步完善设计方案。</li></ul>",18)])])}const D=i(s,[["render",o]]);export{S as __pageData,D as default};
